import {TAU,rad,deg,mod,clamp,C,add,sub,mul,dot,cross,length,unit,eulerBasis,xPose,spinZ,box,cylinder,ring,rod,sphere,part,field,choice,define,metric,circleIntersection,circle,sector,sprocket,linkShapes,grouped,linkPose,polylinePath,circleRoute,memo,radialMesh} from './models-motion-helpers.mjs';
const source=(title,url)=>({title,url}),q3=['改变参数会怎样影响运动？','哪些条件下输出匀速？','这个教学模型省略了哪些工程因素？'];
const universalSources=[source('Belden：万向节叉头相位与轴线布置','https://beldenuniversal.com/knowledge/technical-information/universal-joint-phasing'),source('Spicer：传动轴工作夹角','https://spicerparts.com/en-emea/calculators/driveline-operating-angle-calculator')];
function fork(side,size,pinRadius=5){const h=size/2;return [cylinder(size*.22,40,[side*42,0,0],C.steel,[0,Math.PI/2,0]),box([12,size+10,12],[side*25,0,0],C.blue),...[-1,1].flatMap(sign=>[box([22,8,12],[side*17,sign*h,0],C.blue),{...ring(8,pinRadius+.3,10,[0,sign*h,0],C.gold),rotation:[Math.PI/2,0,0]}])];}
function cardan(beta,phase){const a=[Math.cos(beta),Math.sin(beta),0],v1=[0,Math.cos(phase),Math.sin(phase)],v2=unit(cross(a,v1)),out=Math.atan2(-dot(v2,[-Math.sin(beta),Math.cos(beta),0]),v2[2]),ratio=Math.cos(beta)/(1-Math.sin(beta)**2*Math.cos(phase)**2);return {a,v1,v2,out,ratio,inputRotation:eulerBasis([1,0,0],v1,cross([1,0,0],v1)),outputRotation:eulerBasis(a,v2,cross(a,v2)),crossRotation:eulerBasis(cross(v1,v2),v1,v2)};}
const universal=define({id:'universal-joint',number:24,title:'单十字轴万向节',description:'调轴间夹角，看输入匀速时输出转速如何波动。',fields:[field('angle','轴间夹角','°',25,0,40),field('jointSize','十字轴跨距','mm',36,28,56)],
 build(p){const h=p.jointSize/2;return {parts:[part('input','输入叉头',fork(-1,p.jointSize)),part('output','输出叉头',fork(1,p.jointSize)),part('cross','十字轴',[rod([0,-h-5,0],[0,h+5,0],5),rod([0,0,-h-5],[0,0,h+5],5),sphere(7)]),part('support','输入支承',[ring(p.jointSize*.22+9.5,p.jointSize*.22+.5,12,[0,0,0],C.dark)],[-65,0,0],'housing')]};},
 sample(p,phase){const g=cardan(rad(p.angle),phase);return {poses:{input:{rotation:g.inputRotation},output:{rotation:g.outputRotation},cross:{rotation:g.crossRotation},support:{rotation:[0,Math.PI/2,0]}},metrics:[metric('输入转速',p.inputRPM,'r/min'),metric('瞬时输出转速',p.inputRPM*g.ratio,'r/min'),metric('瞬时角速比',g.ratio),metric('夹角',p.angle,'°')],status:p.angle===0?'两轴共线，瞬时速比为1。':'每转出现两次速度波动；叉头与十字轴始终共享垂直销轴。'};},principle:[{title:'角速度波动',text:'夹角非零时，十字轴约束使输出角速度周期变化。这里相位零点按叉头销轴定义。',formula:'tan θ₂ = tan θ₁ / cos β；ω₂/ω₁ = cos β /(1 − sin²β cos²θ₁)'}],sources:universalSources,limits:'轴承、润滑和间隙为结构示意，40°仅用于放大运动关系，不是允许的连续运行角度或转速额定值。',questions:q3});
function doubleState(p,phase){const b1=rad(p.angle1),b2=rad(p.angle2),g=cardan(b1,phase),aout=[Math.cos(b1-b2),Math.sin(b1-b2),0],error=rad(p.phaseError);const vm=add(mul(g.v2,Math.cos(error)),mul(cross(g.a,g.v2),Math.sin(error))),vo=unit(cross(aout,vm)),bout=[-aout[1],aout[0],0],out=Math.atan2(-vo[2],-dot(vo,bout));return {g,vm,vo,aout,out};}
const doubleJoint=define({id:'double-universal',number:25,title:'双万向节传动轴',description:'调整夹角和叉头相位，找出抵消转速波动的条件。',fields:[field('angle1','第一工作夹角','°',25,0,40),field('angle2','第二工作夹角','°',25,0,40),field('phaseError','叉头相位误差','°',0,-90,90),field('shaftLength','中间轴长度','mm',140,100,220)],
 build(p){const b=rad(p.angle1),j2=[p.shaftLength*Math.cos(b),p.shaftLength*Math.sin(b),0];return {parts:[part('input','输入叉头',fork(-1,32,4)),part('midA','中间轴前叉',fork(1,32,4)),part('crossA','第一十字轴',[rod([0,-21,0],[0,21,0],4),rod([0,0,-21],[0,0,21],4)]),part('tube','中间传动轴',[rod([45*Math.cos(b),45*Math.sin(b),0],[(p.shaftLength-45)*Math.cos(b),(p.shaftLength-45)*Math.sin(b),0],7)]),part('midB','中间轴后叉',fork(-1,32,4),j2),part('output','输出叉头',fork(1,32,4),j2),part('crossB','第二十字轴',[rod([0,-21,0],[0,21,0],4),rod([0,0,-21],[0,0,21],4)],j2)]};},
 sample(p,phase){const s=doubleState(p,phase),e=1e-5,a=doubleState(p,phase-e).out,b=doubleState(p,phase+e).out,ratio=Math.atan2(Math.sin(b-a),Math.cos(b-a))/(2*e),j2=mul(s.g.a,p.shaftLength);return {poses:{input:{rotation:s.g.inputRotation},midA:{rotation:s.g.outputRotation},crossA:{rotation:s.g.crossRotation},midB:{position:j2,rotation:eulerBasis(s.g.a,s.vm,cross(s.g.a,s.vm))},output:{position:j2,rotation:eulerBasis(s.aout,s.vo,cross(s.aout,s.vo))},crossB:{position:j2,rotation:eulerBasis(cross(s.vm,s.vo),s.vm,s.vo)}},metrics:[metric('中间轴瞬时转速',p.inputRPM*s.g.ratio,'r/min'),metric('输出瞬时转速',p.inputRPM*ratio,'r/min'),metric('输出瞬时速比',ratio),metric('叉头误差',p.phaseError,'°')],status:Math.abs(p.angle1-p.angle2)<1e-8&&p.phaseError===0?'两工作角相等、叉头相位正确：第二节抵消第一节的速度波动。':'夹角不等或叉头相位偏离时，输出仍有速度波动。'};},principle:[{title:'抵消条件',text:'正确相位的两节、相等工作角及规定轴线布置共同形成等速输出；中间轴仍非匀速。',formula:'β₁=β₂，Δφ=0 ⇒ ωout/ωin=1'}],sources:universalSources,limits:'采用共面轴线与理想刚性十字轴，无轴扭转、轴承间隙或临界转速校核。',questions:q3});

const clutch=define({id:'friction-clutch',cameraDirection:[2.4,0.4,1],number:28,title:'摩擦片离合器',description:'操作压盘，观察飞轮、摩擦片接合与分离。',fields:[choice('mode','压盘工况','engaged',[['engaged','压紧接合'],['slipping','给定滑差'],['open','完全分离']]),field('normalForce','轴向压紧力','N',1000,0,3000,50),field('friction','摩擦系数','',.3,.1,.6,.01),field('outerRadius','摩擦片外半径','mm',55,35,80),{...field('slip','演示滑差','%',30,0,100),enabledWhen:p=>p.mode==='slipping'&&p.normalForce>0,inactiveHint:'仅在给定滑差工况且压紧力大于0时生效。'}],
 build(p){const R=p.outerRadius;return {parts:[part('flywheel','飞轮与输入轴',[ring(R+8,10,12,[0,0,-18],C.steel),cylinder(9,60,[0,0,-45]),box([R*.65,2,1],[R*.4,0,-25],C.gold)]),part('disc','双面摩擦片',[ring(R,R*.45,4,[0,0,0],C.rubber),ring(R*.45,7,7,[0,0,0],C.gold),box([R*.5,2,1],[R*.5,0,3],C.gold),cylinder(6,70,[0,0,38],C.blue)]),part('pressure','压盘',[ring(R+4,12,8,[0,0,0],C.blue),...Array.from({length:6},(_,i)=>{const a=i*TAU/6;return [cylinder(3,10,[R*.75*Math.cos(a),R*.75*Math.sin(a),7],C.gold),rod([R*.62*Math.cos(a),R*.62*Math.sin(a),4],[15*Math.cos(a),15*Math.sin(a),20],1.6,C.steel)];}).flat()]),part('release','分离拨叉与轴承',[ring(21,7,6,[0,0,19],C.steel),rod([-R-12,-20,19],[-R-12,20,19],4),rod([-R-12,20,19],[0,20,19],4),rod([-R-12,-20,19],[0,-20,19],4)], [0,0,0],'housing')]};},
 sample(p,phase){const pressed=p.mode!=='open'&&p.normalForce>0,ratio=!pressed?0:p.mode==='slipping'?1-p.slip/100:1,R=p.outerRadius/1000,r=R*.45,mean=2*(R**3-r**3)/(3*(R*R-r*r)),cap=pressed?2*p.friction*p.normalForce*mean:0,gap=pressed?0:16;return {poses:{flywheel:spinZ([0,0,0],phase),disc:spinZ([0,0,-10+gap/2],phase*ratio),pressure:spinZ([0,0,-4+gap],phase),release:{position:[0,0,gap]}},metrics:[metric('给定输出转速',p.inputRPM*ratio,'r/min'),metric('双面转矩容量',cap,'N·m'),metric('滑差转速',p.inputRPM*(1-ratio),'r/min'),metric('压盘分离间隙',gap,'mm')],status:!pressed?'压盘分离或无压紧力；输出轴按静止基准显示。':p.mode==='slipping'?'输出滑差为用户指定演示值，不由容量虚构加速过程。':'压盘夹住双面摩擦片，按负载不超过容量的同步基准演示。'};},principle:[{title:'压紧与容量',text:'单片双面摩擦结构含两个接触面。均匀压力假设下，压紧力及摩擦系数决定容量；滑差时会产生热。',formula:'Tcap=2 μ F Rm；Rm=2(R³−r³)/(3(R²−r²))'}],sources:[source('Nexen：离合器容量与滑差发热','https://www.nexengroup.com/resources/faq'),source('Jönköping University：制动器与离合器','https://mechanics.ju.se/MachineElements/brakes-clutches.html')],limits:'摩擦片、飞轮和压盘为真实分件。输出速度是选定工况基准，不求惯量、接合冲击、温升或实际负载下的加速。',questions:['压紧力为何影响转矩容量？','为什么分离后输出不再被输入约束？','滑差如何产生热？']});

function rollerCamOutline(p){const n=p.rollers,rr=p.rollerRadius,rc=42-rr,period=TAU/n,points=[];for(let i=0;i<n*192;i++){const a=i*TAU/(n*192),f=mod(a,period)/period;let r=f<.65?rc-rr-2+2*f/.65:rc-rr+(f-.65)/.35;for(const position of [.1,.65]){const delta=mod(a-position*period+period/2,period)-period/2,side=rc*Math.sin(delta);if(Math.abs(side)<rr)r=Math.min(r,rc*Math.cos(delta)-Math.sqrt(rr*rr-side*side)-.04);}points.push([r*Math.cos(a),r*Math.sin(a)]);}return points;}
const oneWay=define({id:'roller-freewheel',number:29,title:'滚柱式单向离合器',description:'切换相对转向，看滚柱如何楔紧和释放。',fields:[choice('mode','相对运动','lock',[['lock','驱动楔紧'],['overrun','外环超越']]),{...field('overrunRatio','外环超越速比','',1.6,1.05,2.5,.05),enabledWhen:p=>p.mode==='overrun',inactiveHint:'仅在外环超越工况生效；驱动楔紧时内外环同速。'},{...field('rollers','滚柱数量','个',8,6,12),integer:true},field('rollerRadius','滚柱半径','mm',5,4,6,.5)],
 build(p){const n=p.rollers,rr=p.rollerRadius,R=42,rc=R-rr,points=rollerCamOutline(p);const parts=[part('cam','内环楔形凸轮',[{kind:'polygon',points,holes:[circle(8)],depth:18,color:C.blue},cylinder(7,50,[0,0,-30])]),part('outer','外环与输出鼓',[ring(52,R,24,[0,0,0],C.steel),box([9,2,1],[47,0,13],C.gold)]),part('cage','滚柱保持架',[ring(rc+rr*.7,rc-rr*.7,2,[0,0,-13],C.gold)], [0,0,0],'housing')];for(let i=0;i<n;i++)parts.push(grouped(part('roller'+i,i?'滚柱':'楔紧滚柱组',[cylinder(rr,18),box([rr*1.5,1,1],[0,0,9.6],C.dark)]),'rollers',i===0));return {parts};},
 sample(p,phase){const locked=p.mode==='lock',ratio=locked?1:p.overrunRatio,rc=42-p.rollerRadius,offset=(locked?.65:.1)*TAU/p.rollers,poses={cam:spinZ([0,0,0],phase),outer:spinZ([0,0,0],phase*ratio),cage:spinZ([0,0,0],phase)};for(let i=0;i<p.rollers;i++){const a=phase+i*TAU/p.rollers+offset;poses['roller'+i]=spinZ([rc*Math.cos(a),rc*Math.sin(a),0],phase+(ratio-1)*phase*42/p.rollerRadius);}return {poses,metrics:[metric('内环转速',p.inputRPM,'r/min'),metric('外环转速',p.inputRPM*ratio,'r/min'),metric('外环相对转速',p.inputRPM*(ratio-1),'r/min')],status:locked?'滚柱进入收窄楔口，内外环同速传动。':'外环超越，滚柱退入较宽区域，解除楔紧约束。'};},principle:[{title:'单向约束',text:'滚柱位于内凸轮和外圆环之间；一个相对转向使其楔紧，反向或输出超越使其释放。',formula:'锁止：ωout=ωin；超越：ωout>ωin'}],sources:[source('Stieber：超越离合器与滚柱楔紧结构','https://www.stieberclutch.com/-/media/Files/Literature/Brand/stieber-clutch/catalogs/mcc-p-7426-sc-en-a4-web.ashx')],limits:'楔口为可观察的教学轮廓，未根据摩擦角计算自锁或额定转矩；超越速度由用户指定，滚柱转动是相对滚动示意。',questions:['哪个相对转向会楔紧？','为什么外环可以跑得更快？','滚柱与普通滚动轴承有何不同？']});
function centrifugalState(p){const omega=p.inputRPM*TAU/60,m=p.shoeMass,r=.027,gap=.005,k=p.springK*1000,pre=p.preload,a=m*omega*omega,displacement=a>=k?gap:clamp((a*r-pre)/(k-a),0,gap),normal=Math.max(0,a*(r+gap)-pre-k*gap),contact=displacement>=gap-1e-10;return {omega,displacement,normal,contact,threshold:Math.sqrt((pre+k*gap)/(m*(r+gap)))*60/TAU};}
function shoeGuideHalves(points,sign){const result=[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length],inside=sign*a[1]>=3.3,next=sign*b[1]>=3.3;if(inside)result.push(a);if(inside!==next){const t=(sign*3.3-a[1])/(b[1]-a[1]);result.push([a[0]+t*(b[0]-a[0]),sign*3.3]);}}return result;}
const centrifugal=define({id:'centrifugal-clutch',number:30,title:'离心离合器',description:'调整转速，看蹄块张开并与离合器鼓接触。',fields:[field('inputRPM','输入转速','r/min',1200,0,3000,10),field('shoeMass','单蹄块质量','kg',.08,.05,.2,.01),field('springK','单蹄弹簧刚度','N/mm',5,2,8,.2),field('preload','弹簧预紧力','N',15,5,35),field('friction','摩擦系数','',.3,.1,.5,.01)],
 build(){const parts=[part('hub','输入轮毂',[cylinder(12,20),cylinder(7,55,[0,0,-34]),...Array.from({length:3},(_,i)=>{const a=i*TAU/3;return rod([10*Math.cos(a),10*Math.sin(a),0],[34*Math.cos(a),34*Math.sin(a),0],3,C.blue);})]),part('drum','输出离合器鼓',[ring(49,42,22,[0,0,0],C.steel),box([5,2,1],[45,0,12],C.gold)])];for(let i=0;i<3;i++){parts.push(part('shoe'+i,'离心蹄块 '+(i+1),[...[-1,1].map(sign=>({kind:'polygon',points:shoeGuideHalves(sector(25,37,-.45,.45),sign),depth:12,color:C.gold})),...[-1,1].map(sign=>({kind:'polygon',points:sector(25,37,-.45,.45),depth:2,position:[0,0,sign*7],color:C.gold}))]));parts.push(grouped(part('spring'+i,'回位弹簧',[{kind:'tube',points:Array.from({length:17},(_,j)=>[13+j*.8,j===0||j===16?0:(j%2?2:-2),10]),radius:.7,color:C.steel}]),'springs',i===0));}return {parts};},
 sample(p,phase){const s=centrifugalState(p),poses={hub:spinZ([0,0,0],phase),drum:spinZ([0,0,0],s.contact?phase:0)};for(let i=0;i<3;i++){const a=phase+i*TAU/3,delta=s.displacement*1000;poses['shoe'+i]=spinZ([delta*Math.cos(a),delta*Math.sin(a),0],a);poses['spring'+i]={rotation:[0,0,a],scale:[1+delta/26,1,1]};}return {poses,metrics:[metric('蹄块径向张开',s.displacement*1000,'mm'),metric('理论接触转速',s.threshold,'r/min'),metric('接触法向力 / 蹄',s.contact?s.normal:0,'N'),metric('三蹄转矩容量',s.contact?3*p.friction*s.normal*.042:0,'N·m')],status:s.contact?'蹄块触鼓；鼓按无负载同步基准转动，未求接合瞬态。':'离心力未克服弹簧及间隙，输出鼓按静止基准显示。'};},principle:[{title:'转速自动接合',text:'准静态径向力平衡决定蹄块外移，达到鼓内半径后建立接触法向力。',formula:'mω²(r₀+δ)=F₀+kδ；δ≤鼓间隙'}],sources:[source('Hilliard：离心离合器自动接合原理','https://www.hilliardcorp.com/products/drivetrain/extreme-duty-clutches/')],limits:'蹄块有真实径向导向槽，导杆和直线弹簧为教学简化；采用准静态力平衡，不预测负载加速、热衰退、磨损或实际接合额定转速。',questions:['为什么提高转速会自动接合？','加强弹簧为何提高接合转速？','蹄块触鼓是否立即等于满转矩？']});

const oldham=define({id:'oldham-coupling',cameraDirection:[3,0.6,1],number:31,title:'奥尔德姆联轴器',description:'改变两根平行轴的偏置，观察中间滑块的补偿运动。',fields:[field('offset','平行轴偏置','mm',10,0,18),field('diameter','联轴器直径','mm',70,60,90)],
 build(p){const R=p.diameter/2,h=8,flange=z=>[cylinder(R,5,[0,0,z]),...[-1,1].map(s=>box([R*1.6,8,5],[0,s*(h/2+4),z+(z<0?5:-5)],C.blue)),cylinder(8,40,[0,0,z+(z<0?-22:22)])];return {parts:[part('input','输入滑槽毂',flange(-13),[-p.offset/2,0,0]),part('output','输出正交滑槽毂',flange(13),[p.offset/2,0,0]),part('disc','中间正交滑块',[cylinder(R*.8,5,[0,0,0],C.gold),box([R*1.5,7,5],[0,0,-5],C.rubber),box([7,R*1.5,5],[0,0,5],C.rubber)])]};},
 sample(p,phase){const e=p.offset,center=[e/2*Math.cos(2*phase),e/2*Math.sin(2*phase),0];return {poses:{input:spinZ([-e/2,0,0],phase),output:spinZ([e/2,0,0],phase+Math.PI/2),disc:spinZ(center,phase)},metrics:[metric('输入 / 输出转速',p.inputRPM,'r/min'),metric('滑块中心轨迹半径',e/2,'mm'),metric('输入侧滑移',e*Math.cos(phase),'mm'),metric('输出侧滑移',e*Math.sin(phase),'mm')],status:e===0?'两轴同心，中间盘中心不平移。':'中间滑块通过两面互相垂直的滑动补偿偏置，两轴保持同速。'};},principle:[{title:'两条正交滑槽',text:'中间盘中心是输入滑槽线和输出滑槽线的交点；中心轨迹转两圈时，两端轴各转一圈。',formula:'C=(e cos2θ/2,e sin2θ/2)；ωout=ωin'}],sources:[source('Ruland：Oldham 滑块补偿偏置','https://www.ruland.com/info-oldham-performance')],limits:'偏置范围为可视教学范围，不是厂商允许偏置；省略磨损、接触压力和轴向/角向误差。',questions:['中间盘为何需要两条正交滑槽？','中间盘中心为什么每转绕两圈？','输出转速会随偏置变化吗？']});

function wiperState(p,phase){const O=[-105,-50,0],A=[-105,40,0],A2=[105,40,0],P=add(O,[p.crankRadius*Math.cos(phase),p.crankRadius*Math.sin(phase),0]),B=circleIntersection(A,p.rockerLength,P,95,1),angle=Math.atan2(B[1]-A[1],B[0]-A[0]),B2=add(A2,sub(B,A));return {O,A,A2,P,B,B2,angle};}
